const root = $input.first().json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;
const headers = root.headers || {};

const empresa = String(body.empresa || '').trim();
const nome = String(body.nome || '').trim();
const cargo = String(body.cargo || '').trim();

if (!empresa || !nome || !cargo) {
  return [{
    json: {
      ok: false,
      status: 400,
      message: 'Informe empresa, nome e cargo.',
      row: null,
    },
  }];
}

const respostas = body.respostas && typeof body.respostas === 'object'
  ? body.respostas
  : {
      empresa,
      nome,
      cargo,
      controle: body.controle || null,
      auditor: body.auditor || null,
      cruzamento: body.cruzamento || null,
      divergencia: body.divergencia || null,
      banco: body.banco || null,
      cct_quem: body.cct_quem || null,
      reclamacao: body.reclamacao || null,
      maior_dor: body.maior_dor || null,
    };

const finishedAt = body.finished_at || new Date().toISOString();
const userAgent = String(
  body.user_agent || headers['user-agent'] || headers['User-Agent'] || ''
).slice(0, 500);

return [{
  json: {
    ok: true,
    status: 200,
    message: 'ok',
    row: {
      empresa,
      nome,
      cargo,
      controle: body.controle || null,
      auditor: body.auditor || null,
      cruzamento: body.cruzamento || null,
      divergencia: body.divergencia || null,
      banco: body.banco || null,
      cct_quem: body.cct_quem || null,
      reclamacao: body.reclamacao || null,
      maior_dor: body.maior_dor || null,
      respostas,
      finished_at: finishedAt,
      user_agent: userAgent || null,
      origem: body.origem || 'diagnostico-jornada',
    },
  },
}];

const saved = $input.first().json;
const rows = Array.isArray(saved) ? saved : (saved && saved.id ? [saved] : (saved && saved.body ? (Array.isArray(saved.body) ? saved.body : [saved.body]) : []));
const row = rows.find((r) => r && r.id) || null;
if (!row) {
  const detail = typeof saved === 'object' ? JSON.stringify(saved).slice(0, 400) : String(saved);
  return [{
    json: {
      ok: false,
      status: 502,
      message: 'Não foi possível salvar no banco.',
      detail,
    },
  }];
}
return [{
  json: {
    ok: true,
    status: 201,
    message: 'Respostas salvas.',
    id: row.id,
    created_at: row.created_at || null,
  },
}];
